mapper.select:
SELECT id, actor_type AS actorType, actor_id AS actorId, idempotency_key AS idempotencyKey,
       route_id AS routeId, fingerprint, status, visibility_status AS visibilityStatus,
       course_id AS courseId, created_at AS createdAt, updated_at AS updatedAt
FROM upload_operation
WHERE actor_type = #{actorType}
  AND actor_id = #{actorId}
  AND idempotency_key = #{idempotencyKey}
  AND route_id = #{routeId}
